// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { strongestLinks } from "../../../main/frontend/graph-explorer/graph-layout-multilevel.ts";

// Links between neighbourhoods, keyed "a:b" (a < b), weighted by how many statements join them.
const weights = new Map([
  ["0:1", 5],
  ["0:2", 1],
  ["0:3", 3],
  ["1:2", 2],
  ["2:3", 4],
]);

test("each neighbourhood keeps its strongest links to the others, so the coarse layout stays small", () => {
  assert.deepEqual([...strongestLinks(weights, 1)].sort(), ["0:1", "2:3"]);
  assert.deepEqual([...strongestLinks(weights, 2)].sort(), ["0:1", "0:3", "1:2", "2:3"], "0:2 is no one's two strongest");
  assert.deepEqual([...strongestLinks(weights, 10)].sort(), [...weights.keys()].sort());
});

test("a dense quotient graph is cut to at most `perCluster` links per neighbourhood", () => {
  // 221 neighbourhoods all linked to each other, as a 50,000-node random graph gives.
  const dense = new Map();
  for (let a = 0; a < 221; a++) for (let b = a + 1; b < 221; b++) dense.set(`${a}:${b}`, ((a * 31 + b * 17) % 23) + 1);
  const kept = strongestLinks(dense, 6);
  assert.ok(kept.size <= 221 * 6, `${kept.size} links kept`);
  const ends = new Set([...kept].flatMap((key) => key.split(":")));
  assert.equal(ends.size, 221, "every neighbourhood keeps a link");
});
